<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>T-Shirt Print Alignment Press Game</title>
<style>
  :root{
    --bg:#f4f7f6;
    --panel:#ffffff;
    --ink:#17202a;
    --muted:#667085;
    --line:#d7dee8;
    --soft:#eaf0f4;
    --accent:#2f6fed;
    --accent2:#12a594;
    --warn:#b7791f;
    --bad:#c2410c;
    --good:#15803d;
    --shirt:#f7f9fb;
    --print:#e9f3ff;
    --shadow:0 18px 50px rgba(16,24,40,.12);
    --radius:22px;
  }

  *{box-sizing:border-box}

  body{
    margin:0;
    font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    background:
      radial-gradient(circle at top left, #dff5ef 0, transparent 34%),
      radial-gradient(circle at top right, #dfeaff 0, transparent 32%),
      var(--bg);
    color:var(--ink);
  }

  button,input,select,textarea{
    font:inherit;
  }

  button{
    border:0;
    cursor:pointer;
  }

  .app{
    width:min(1180px, 100%);
    margin:0 auto;
    padding:18px;
  }

  .hero{
    display:grid;
    grid-template-columns:1.2fr .8fr;
    gap:16px;
    align-items:stretch;
    margin-bottom:16px;
  }

  .card{
    background:rgba(255,255,255,.88);
    border:1px solid rgba(215,222,232,.9);
    box-shadow:var(--shadow);
    border-radius:var(--radius);
    overflow:hidden;
  }

  .intro{
    padding:22px;
  }

  h1{
    margin:0 0 8px;
    font-size:clamp(1.45rem, 3vw, 2.45rem);
    line-height:1.05;
    letter-spacing:0;
  }

  .sub{
    margin:0;
    color:var(--muted);
    line-height:1.45;
    max-width:72ch;
  }

  .scoreCard{
    padding:18px;
    display:grid;
    align-content:center;
    gap:12px;
  }

  .scoreTop{
    display:flex;
    justify-content:space-between;
    align-items:end;
    gap:12px;
  }

  .score{
    font-size:2.6rem;
    font-weight:900;
    line-height:1;
  }

  .badge{
    display:inline-flex;
    align-items:center;
    gap:7px;
    border-radius:999px;
    padding:7px 10px;
    background:#edf7f5;
    color:#0f766e;
    font-weight:800;
    font-size:.85rem;
  }

  .meter{
    height:12px;
    background:#e5eaf1;
    border-radius:999px;
    overflow:hidden;
  }

  .meterFill{
    width:0%;
    height:100%;
    background:linear-gradient(90deg, var(--bad), var(--warn), var(--good));
    border-radius:999px;
    transition:width .2s ease;
  }

  .main{
    display:grid;
    grid-template-columns:330px 1fr 320px;
    gap:16px;
    align-items:start;
  }

  .panel{
    padding:16px;
  }

  .panel h2{
    margin:0 0 12px;
    font-size:1.05rem;
  }

  .field{
    display:grid;
    gap:6px;
    margin-bottom:12px;
  }

  label{
    font-weight:800;
    font-size:.86rem;
  }

  input,select,textarea{
    width:100%;
    border:1px solid var(--line);
    border-radius:14px;
    padding:10px 11px;
    background:#fff;
    color:var(--ink);
  }

  textarea{
    min-height:80px;
    resize:vertical;
  }

  .row{
    display:grid;
    grid-template-columns:1fr 1fr;
    gap:10px;
  }

  .actions{
    display:flex;
    flex-wrap:wrap;
    gap:9px;
    margin-top:12px;
  }

  .btn{
    border-radius:14px;
    padding:10px 12px;
    background:var(--ink);
    color:#fff;
    font-weight:850;
  }

  .btn.secondary{
    background:#edf2f7;
    color:#111827;
  }

  .btn.accent{
    background:var(--accent);
  }

  .btn.good{
    background:var(--accent2);
  }

  .btn.danger{
    background:#fff1ed;
    color:#9a3412;
    border:1px solid #fed7aa;
  }

  .stageCard{
    padding:16px;
  }

  .toolbar{
    display:flex;
    justify-content:space-between;
    gap:12px;
    align-items:center;
    margin-bottom:12px;
    flex-wrap:wrap;
  }

  .hint{
    color:var(--muted);
    font-size:.9rem;
    line-height:1.35;
  }

  .stageWrap{
    display:grid;
    place-items:center;
    min-height:620px;
    background:
      linear-gradient(90deg, rgba(23,32,42,.045) 1px, transparent 1px),
      linear-gradient(rgba(23,32,42,.045) 1px, transparent 1px);
    background-size:24px 24px;
    border:1px solid var(--line);
    border-radius:24px;
    padding:18px;
    overflow:hidden;
  }

  .shirt{
    position:relative;
    width:min(520px, 100%);
    aspect-ratio: 0.78 / 1;
    user-select:none;
    touch-action:none;
  }

  .shirtShape{
    position:absolute;
    inset:2% 7% 1% 7%;
    background:var(--shirt);
    border:2px solid #cbd5e1;
    border-radius:28% 28% 18% 18% / 12% 12% 10% 10%;
    box-shadow:inset 0 0 0 1px rgba(255,255,255,.8), 0 18px 45px rgba(15,23,42,.11);
  }

  .sleeve{
    position:absolute;
    top:11%;
    width:25%;
    height:22%;
    background:var(--shirt);
    border:2px solid #cbd5e1;
    z-index:0;
  }

  .sleeve.left{
    left:0;
    transform:rotate(18deg);
    border-radius:50% 12% 30% 30%;
  }

  .sleeve.right{
    right:0;
    transform:rotate(-18deg);
    border-radius:12% 50% 30% 30%;
  }

  .neck{
    position:absolute;
    top:2.4%;
    left:50%;
    transform:translateX(-50%);
    width:27%;
    height:13%;
    background:var(--bg);
    border:2px solid #cbd5e1;
    border-top:0;
    border-radius:0 0 50% 50%;
    z-index:2;
  }

  .printArea{
    position:absolute;
    left:24%;
    top:21%;
    width:52%;
    height:48%;
    background:rgba(47,111,237,.08);
    border:2px dashed rgba(47,111,237,.7);
    border-radius:18px;
    z-index:3;
  }

  .centerLineV,
  .centerLineH{
    position:absolute;
    background:rgba(18,165,148,.55);
    pointer-events:none;
    z-index:4;
  }

  .centerLineV{
    left:50%;
    top:21%;
    width:2px;
    height:48%;
  }

  .centerLineH{
    left:24%;
    top:45%;
    width:52%;
    height:2px;
  }

  .safeLabel{
    position:absolute;
    left:24%;
    top:18%;
    font-size:.78rem;
    color:#245bc6;
    font-weight:900;
    z-index:5;
  }

  .block{
    position:absolute;
    z-index:10;
    min-width:54px;
    min-height:32px;
    display:grid;
    place-items:center;
    padding:8px 10px;
    border:2px solid rgba(23,32,42,.82);
    background:rgba(255,255,255,.85);
    color:#111827;
    border-radius:12px;
    cursor:grab;
    box-shadow:0 8px 18px rgba(15,23,42,.14);
    transform:translate(-50%, -50%);
    white-space:pre-wrap;
    text-align:center;
    max-width:210px;
  }

  .block:active{
    cursor:grabbing;
  }

  .block.selected{
    outline:3px solid rgba(47,111,237,.35);
    outline-offset:4px;
  }

  .block.text{
    font-weight:900;
  }

  .block.icon{
    font-size:2rem;
    line-height:1;
  }

  .block.small{font-size:.9rem}
  .block.medium{font-size:1.18rem}
  .block.large{font-size:1.55rem}
  .block.xlarge{font-size:2rem}

  .issueList{
    display:grid;
    gap:8px;
    margin:0;
    padding:0;
    list-style:none;
  }

  .issue{
    border:1px solid var(--line);
    border-radius:14px;
    padding:10px;
    background:#fff;
    display:grid;
    gap:3px;
  }

  .issue strong{
    font-size:.9rem;
  }

  .issue span{
    color:var(--muted);
    font-size:.84rem;
    line-height:1.35;
  }

  .issue.good{
    border-color:#bbf7d0;
    background:#f0fdf4;
  }

  .issue.warn{
    border-color:#fde68a;
    background:#fffbeb;
  }

  .issue.bad{
    border-color:#fed7aa;
    background:#fff7ed;
  }

  .blockList{
    display:grid;
    gap:8px;
    margin-top:10px;
  }

  .blockItem{
    display:flex;
    justify-content:space-between;
    align-items:center;
    gap:10px;
    border:1px solid var(--line);
    background:#fff;
    border-radius:14px;
    padding:9px;
  }

  .blockItem button{
    border-radius:10px;
    padding:7px 9px;
    background:#edf2f7;
    color:#111827;
    font-weight:800;
  }

  .status{
    min-height:22px;
    color:var(--muted);
    font-size:.88rem;
    line-height:1.35;
    margin-top:10px;
  }

  .manualBox{
    margin-top:10px;
    display:none;
  }

  .manualBox.show{
    display:block;
  }

  .manualBox textarea{
    min-height:150px;
    font-family:ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    font-size:.82rem;
  }

  .specPreview{
    min-height:150px;
    background:#0f172a;
    color:#e5e7eb;
    border-radius:16px;
    padding:12px;
    overflow:auto;
    white-space:pre-wrap;
    font-family:ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    font-size:.8rem;
    line-height:1.45;
  }

  .pillRow{
    display:flex;
    gap:8px;
    flex-wrap:wrap;
  }

  .pill{
    background:#f1f5f9;
    border:1px solid var(--line);
    color:#334155;
    padding:7px 9px;
    border-radius:999px;
    font-size:.82rem;
    font-weight:800;
  }

  @media (max-width: 1040px){
    .main{
      grid-template-columns:1fr;
    }
    .hero{
      grid-template-columns:1fr;
    }
    .stageWrap{
      min-height:auto;
    }
  }

  @media (max-width: 520px){
    .app{
      padding:10px;
    }
    .intro,.scoreCard,.panel,.stageCard{
      padding:14px;
    }
    .row{
      grid-template-columns:1fr;
    }
    .toolbar{
      align-items:flex-start;
    }
    .stageWrap{
      padding:8px;
      border-radius:18px;
    }
    .shirt{
      width:100%;
    }
    .btn{
      width:100%;
    }
    .actions{
      display:grid;
    }
  }
</style>
</head>
<body>
<div class="app">
  <section class="hero">
    <div class="card intro">
      <h1>T-Shirt Print Alignment Press Game</h1>
      <p class="sub">Arrange text and icon blocks on a shirt mockup, keep the design inside the print-safe area, check readability, and export an order-ready production spec.</p>
    </div>
    <div class="card scoreCard">
      <div class="scoreTop">
        <div>
          <div class="badge" id="gradeBadge">Ready check</div>
          <div class="hint">Score updates as you move, resize, and edit blocks.</div>
        </div>
        <div class="score" id="score">0</div>
      </div>
      <div class="meter"><div class="meterFill" id="meterFill"></div></div>
      <div class="pillRow" id="summaryPills"></div>
    </div>
  </section>

  <main class="main">
    <aside class="card panel">
      <h2>Design Controls</h2>

      <div class="field">
        <label for="orderName">Order name</label>
        <input id="orderName" value="Weekend Market Staff Tee" maxlength="80">
      </div>

      <div class="row">
        <div class="field">
          <label for="shirtColor">Shirt color</label>
          <select id="shirtColor">
            <option value="#f7f9fb">White</option>
            <option value="#111827">Black</option>
            <option value="#e2e8f0">Heather gray</option>
            <option value="#dbeafe">Powder blue</option>
            <option value="#dcfce7">Mint</option>
            <option value="#fee2e2">Washed rose</option>
          </select>
        </div>
        <div class="field">
          <label for="printMethod">Print method</label>
          <select id="printMethod">
            <option>DTG</option>
            <option>Screen print</option>
            <option>Heat transfer vinyl</option>
            <option>Embroidery patch guide</option>
          </select>
        </div>
      </div>

      <div class="field">
        <label for="blockType">New block type</label>
        <select id="blockType">
          <option value="text">Text</option>
          <option value="icon">Icon</option>
        </select>
      </div>

      <div class="field">
        <label for="blockText">Text or icon</label>
        <input id="blockText" value="FRESH PRESS" maxlength="80">
      </div>

      <div class="row">
        <div class="field">
          <label for="blockSize">Size</label>
          <select id="blockSize">
            <option value="small">Small</option>
            <option value="medium" selected>Medium</option>
            <option value="large">Large</option>
            <option value="xlarge">XL</option>
          </select>
        </div>
        <div class="field">
          <label for="inkColor">Ink color</label>
          <select id="inkColor">
            <option value="#111827">Black ink</option>
            <option value="#ffffff">White ink</option>
            <option value="#2f6fed">Blue ink</option>
            <option value="#12a594">Teal ink</option>
            <option value="#ef4444">Red ink</option>
            <option value="#f59e0b">Gold ink</option>
          </select>
        </div>
      </div>

      <div class="actions">
        <button class="btn accent" id="addBlock">Add block</button>
        <button class="btn secondary" id="centerSelected">Center selected</button>
        <button class="btn danger" id="deleteSelected">Delete selected</button>
      </div>

      <h2 style="margin-top:18px">Blocks</h2>
      <div class="blockList" id="blockList"></div>
    </aside>

    <section class="card stageCard">
      <div class="toolbar">
        <div>
          <h2 style="margin:0 0 4px">Press Mockup</h2>
          <div class="hint">Drag blocks. Keep everything inside the dashed print-safe zone.</div>
        </div>
        <div class="actions" style="margin:0">
          <button class="btn secondary" id="resetDemo">Reset sample</button>
        </div>
      </div>

      <div class="stageWrap">
        <div class="shirt" id="shirt">
          <div class="sleeve left"></div>
          <div class="sleeve right"></div>
          <div class="shirtShape"></div>
          <div class="neck"></div>
          <div class="safeLabel">PRINT-SAFE AREA</div>
          <div class="printArea" id="printArea"></div>
          <div class="centerLineV"></div>
          <div class="centerLineH"></div>
        </div>
      </div>
    </section>

    <aside class="card panel">
      <h2>Production Checks</h2>
      <ul class="issueList" id="issueList"></ul>

      <h2 style="margin-top:18px">Order-Ready Spec</h2>
      <div class="specPreview" id="specPreview"></div>

      <div class="actions">
        <button class="btn good" id="copySpec">Copy spec</button>
        <button class="btn secondary" id="downloadSpec">Download .txt</button>
      </div>
      <div class="status" id="status"></div>
      <div class="manualBox" id="manualBox">
        <label for="manualText">Manual copy fallback</label>
        <textarea id="manualText" readonly></textarea>
      </div>
    </aside>
  </main>
</div>

<script>
(function(){
  "use strict";

  var blocks = [];
  var selectedId = null;
  var dragState = null;

  var els = {
    shirt: document.getElementById("shirt"),
    printArea: document.getElementById("printArea"),
    orderName: document.getElementById("orderName"),
    shirtColor: document.getElementById("shirtColor"),
    printMethod: document.getElementById("printMethod"),
    blockType: document.getElementById("blockType"),
    blockText: document.getElementById("blockText"),
    blockSize: document.getElementById("blockSize"),
    inkColor: document.getElementById("inkColor"),
    addBlock: document.getElementById("addBlock"),
    centerSelected: document.getElementById("centerSelected"),
    deleteSelected: document.getElementById("deleteSelected"),
    resetDemo: document.getElementById("resetDemo"),
    blockList: document.getElementById("blockList"),
    issueList: document.getElementById("issueList"),
    specPreview: document.getElementById("specPreview"),
    copySpec: document.getElementById("copySpec"),
    downloadSpec: document.getElementById("downloadSpec"),
    status: document.getElementById("status"),
    manualBox: document.getElementById("manualBox"),
    manualText: document.getElementById("manualText"),
    score: document.getElementById("score"),
    meterFill: document.getElementById("meterFill"),
    gradeBadge: document.getElementById("gradeBadge"),
    summaryPills: document.getElementById("summaryPills")
  };

  function uid(){
    return "b" + Math.random().toString(36).slice(2, 9);
  }

  function clamp(value, min, max){
    return Math.max(min, Math.min(max, value));
  }

  function contrastRatio(hexA, hexB){
    function parse(hex){
      var clean = hex.replace("#", "");
      var r = parseInt(clean.slice(0,2), 16) / 255;
      var g = parseInt(clean.slice(2,4), 16) / 255;
      var b = parseInt(clean.slice(4,6), 16) / 255;
      return [r,g,b].map(function(v){
        return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
      });
    }
    var a = parse(hexA);
    var b = parse(hexB);
    var la = 0.2126 * a[0] + 0.7152 * a[1] + 0.0722 * a[2];
    var lb = 0.2126 * b[0] + 0.7152 * b[1] + 0.0722 * b[2];
    var high = Math.max(la, lb);
    var low = Math.min(la, lb);
    return (high + 0.05) / (low + 0.05);
  }

  function sizeLabel(size){
    var map = {
      small:"small",
      medium:"medium",
      large:"large",
      xlarge:"XL"
    };
    return map[size] || "medium";
  }

  function blockTextFallback(type){
    if(type === "icon"){ return "★"; }
    return "FRESH PRESS";
  }

  function addBlockFromControls(){
    var type = els.blockType.value;
    var text = els.blockText.value.trim() || blockTextFallback(type);
    var block = {
      id: uid(),
      type: type,
      text: text,
      size: els.blockSize.value,
      ink: els.inkColor.value,
      x: 50 + (Math.random() * 8 - 4),
      y: 40 + (Math.random() * 8 - 4)
    };
    blocks.push(block);
    selectedId = block.id;
    render();
  }

  function resetSample(){
    blocks = [
      {id:uid(), type:"text", text:"FRESH PRESS", size:"large", ink:"#111827", x:50, y:34},
      {id:uid(), type:"icon", text:"✦", size:"xlarge", ink:"#12a594", x:50, y:46},
      {id:uid(), type:"text", text:"CINCY MARKET CREW", size:"small", ink:"#111827", x:50, y:58}
    ];
    selectedId = blocks[0].id;
    els.orderName.value = "Weekend Market Staff Tee";
    els.shirtColor.value = "#f7f9fb";
    els.printMethod.value = "DTG";
    render();
  }

  function getSelected(){
    return blocks.find(function(b){ return b.id === selectedId; }) || null;
  }

  function selectBlock(id){
    selectedId = id;
    render();
  }

  function createBlockNode(block){
    var node = document.createElement("div");
    node.className = "block " + block.type + " " + block.size + (block.id === selectedId ? " selected" : "");
    node.style.left = block.x + "%";
    node.style.top = block.y + "%";
    node.style.color = block.ink;
    node.dataset.id = block.id;
    node.tabIndex = 0;
    node.setAttribute("role", "button");
    node.setAttribute("aria-label", "Design block " + block.text);
    node.textContent = block.text;

    node.addEventListener("pointerdown", function(ev){
      ev.preventDefault();
      selectedId = block.id;
      var rect = els.shirt.getBoundingClientRect();
      dragState = {
        id:block.id,
        rect:rect
      };
      node.setPointerCapture(ev.pointerId);
      moveBlockFromPointer(ev);
      render();
    });

    node.addEventListener("pointermove", function(ev){
      if(dragState && dragState.id === block.id){
        moveBlockFromPointer(ev);
      }
    });

    node.addEventListener("pointerup", function(ev){
      if(dragState && dragState.id === block.id){
        dragState = null;
        try{ node.releasePointerCapture(ev.pointerId); }catch(e){}
        render();
      }
    });

    node.addEventListener("keydown", function(ev){
      var step = ev.shiftKey ? 3 : 1;
      var target = blocks.find(function(b){ return b.id === block.id; });
      if(!target){ return; }
      if(ev.key === "ArrowLeft"){ target.x = clamp(target.x - step, 5, 95); ev.preventDefault(); }
      if(ev.key === "ArrowRight"){ target.x = clamp(target.x + step, 5, 95); ev.preventDefault(); }
      if(ev.key === "ArrowUp"){ target.y = clamp(target.y - step, 5, 95); ev.preventDefault(); }
      if(ev.key === "ArrowDown"){ target.y = clamp(target.y + step, 5, 95); ev.preventDefault(); }
      render();
    });

    return node;
  }

  function moveBlockFromPointer(ev){
    var block = blocks.find(function(b){ return b.id === dragState.id; });
    if(!block){ return; }
    var x = ((ev.clientX - dragState.rect.left) / dragState.rect.width) * 100;
    var y = ((ev.clientY - dragState.rect.top) / dragState.rect.height) * 100;
    block.x = clamp(x, 5, 95);
    block.y = clamp(y, 5, 95);
    updateBlockPositionOnly(block);
    updateOutputs();
  }

  function updateBlockPositionOnly(block){
    var node = els.shirt.querySelector('[data-id="' + block.id + '"]');
    if(node){
      node.style.left = block.x + "%";
      node.style.top = block.y + "%";
    }
  }

  function renderBlocks(){
    var existing = Array.prototype.slice.call(els.shirt.querySelectorAll(".block"));
    existing.forEach(function(n){ n.remove(); });
    blocks.forEach(function(block){
      els.shirt.appendChild(createBlockNode(block));
    });
  }

  function renderBlockList(){
    var frag = document.createDocumentFragment();
    blocks.forEach(function(block, index){
      var item = document.createElement("div");
      item.className = "blockItem";

      var left = document.createElement("div");
      var title = document.createElement("strong");
      title.textContent = String(index + 1) + ". " + block.text;
      var meta = document.createElement("div");
      meta.className = "hint";
      meta.textContent = block.type + " · " + sizeLabel(block.size) + " · x " + Math.round(block.x) + "% / y " + Math.round(block.y) + "%";
      left.appendChild(title);
      left.appendChild(meta);

      var controls = document.createElement("div");
      controls.style.display = "flex";
      controls.style.gap = "6px";

      var edit = document.createElement("button");
      edit.type = "button";
      edit.textContent = "Edit";
      edit.addEventListener("click", function(){
        selectedId = block.id;
        els.blockType.value = block.type;
        els.blockText.value = block.text;
        els.blockSize.value = block.size;
        els.inkColor.value = block.ink;
        render();
      });

      var apply = document.createElement("button");
      apply.type = "button";
      apply.textContent = "Apply";
      apply.addEventListener("click", function(){
        block.type = els.blockType.value;
        block.text = els.blockText.value.trim() || blockTextFallback(block.type);
        block.size = els.blockSize.value;
        block.ink = els.inkColor.value;
        selectedId = block.id;
        render();
      });

      controls.appendChild(edit);
      controls.appendChild(apply);
      item.appendChild(left);
      item.appendChild(controls);
      frag.appendChild(item);
    });
    els.blockList.replaceChildren(frag);
  }

  function measureBlocks(){
    var shirtRect = els.shirt.getBoundingClientRect();
    var safeRect = els.printArea.getBoundingClientRect();

    return blocks.map(function(block){
      var node = els.shirt.querySelector('[data-id="' + block.id + '"]');
      var rect = node ? node.getBoundingClientRect() : shirtRect;
      return {
        block:block,
        rect:rect,
        insideSafe:
          rect.left >= safeRect.left &&
          rect.right <= safeRect.right &&
          rect.top >= safeRect.top &&
          rect.bottom <= safeRect.bottom,
        centerOffset: Math.abs(block.x - 50),
        verticalTarget: Math.abs(block.y - 45),
        widthPct: (rect.width / shirtRect.width) * 100,
        heightPct: (rect.height / shirtRect.height) * 100
      };
    });
  }

  function buildChecks(){
    var measured = measureBlocks();
    var checks = [];
    var shirtColor = els.shirtColor.value;
    var lowContrast = blocks.filter(function(b){
      return contrastRatio(b.ink, shirtColor) < 3.2;
    });
    var outside = measured.filter(function(m){ return !m.insideSafe; });
    var offCenter = measured.filter(function(m){ return m.centerOffset > 12; });
    var tinyText = blocks.filter(function(b){
      return b.type === "text" && b.size === "small" && b.text.length > 24;
    });
    var crowded = measured.filter(function(m){ return m.widthPct > 46 || m.heightPct > 18; });
    var empty = blocks.length === 0;

    if(empty){
      checks.push({level:"bad", title:"No print blocks yet", detail:"Add at least one text or icon block before sending this to production."});
    }else{
      checks.push({level:"good", title:"Design blocks present", detail:String(blocks.length) + " block" + (blocks.length === 1 ? "" : "s") + " placed on the shirt."});
    }

    if(outside.length){
      checks.push({level:"bad", title:"Print-safe margin issue", detail:String(outside.length) + " block" + (outside.length === 1 ? "" : "s") + " touch or leave the dashed safe area."});
    }else{
      checks.push({level:"good", title:"Safe margins pass", detail:"All blocks sit inside the dashed print-safe area."});
    }

    if(lowContrast.length){
      checks.push({level:"bad", title:"Readability risk", detail:String(lowContrast.length) + " block" + (lowContrast.length === 1 ? "" : "s") + " may not contrast enough with the shirt color."});
    }else{
      checks.push({level:"good", title:"Ink contrast pass", detail:"Ink colors have usable contrast against the selected shirt color."});
    }

    if(offCenter.length){
      checks.push({level:"warn", title:"Alignment warning", detail:String(offCenter.length) + " block" + (offCenter.length === 1 ? "" : "s") + " are more than 12% away from center."});
    }else{
      checks.push({level:"good", title:"Center alignment pass", detail:"Blocks are visually centered enough for a standard front print."});
    }

    if(tinyText.length){
      checks.push({level:"warn", title:"Small-text warning", detail:"Long text at small size may blur or fill in after printing."});
    }else{
      checks.push({level:"good", title:"Text size pass", detail:"Text blocks are large enough for normal viewing distance."});
    }

    if(crowded.length){
      checks.push({level:"warn", title:"Crowding warning", detail:"One or more blocks are large relative to the print zone. Confirm vendor max imprint width."});
    }else{
      checks.push({level:"good", title:"Scale pass", detail:"Block scale looks reasonable for a front chest print."});
    }

    return checks;
  }

  function scoreFromChecks(checks){
    var score = 100;
    checks.forEach(function(check){
      if(check.level === "bad"){ score -= 22; }
      if(check.level === "warn"){ score -= 10; }
    });
    if(blocks.length > 6){ score -= 8; }
    return clamp(score, 0, 100);
  }

  function renderIssues(checks){
    var frag = document.createDocumentFragment();
    checks.forEach(function(check){
      var li = document.createElement("li");
      li.className = "issue " + check.level;
      var strong = document.createElement("strong");
      strong.textContent = check.title;
      var span = document.createElement("span");
      span.textContent = check.detail;
      li.appendChild(strong);
      li.appendChild(span);
      frag.appendChild(li);
    });
    els.issueList.replaceChildren(frag);
  }

  function buildSpec(){
    var lines = [];
    var checks = buildChecks();
    var score = scoreFromChecks(checks);

    lines.push("T-SHIRT PRINT LAYOUT SPEC");
    lines.push("Order name: " + (els.orderName.value.trim() || "Untitled T-shirt order"));
    lines.push("Print method: " + els.printMethod.value);
    lines.push("Shirt color: " + els.shirtColor.options[els.shirtColor.selectedIndex].text + " (" + els.shirtColor.value + ")");
    lines.push("Readiness score: " + score + "/100");
    lines.push("");
    lines.push("Mockup coordinate system:");
    lines.push("- x/y are percentages of the full shirt mockup.");
    lines.push("- Print-safe zone is x 24%-76%, y 21%-69%.");
    lines.push("- Center front reference is x 50%, y 45%.");
    lines.push("");
    lines.push("Blocks:");
    if(!blocks.length){
      lines.push("- No blocks added.");
    }else{
      blocks.forEach(function(b, i){
        lines.push(
          String(i + 1) + ". " +
          b.type.toUpperCase() +
          " | content: " + JSON.stringify(b.text) +
          " | size: " + sizeLabel(b.size) +
          " | ink: " + b.ink +
          " | x: " + b.x.toFixed(1) + "% | y: " + b.y.toFixed(1) + "%"
        );
      });
    }
    lines.push("");
    lines.push("Production checks:");
    checks.forEach(function(c){
      lines.push("- " + c.level.toUpperCase() + ": " + c.title + " — " + c.detail);
    });
    lines.push("");
    lines.push("Vendor note:");
    lines.push("Please center the design on the garment front. Keep all artwork within the print-safe zone unless manually approved. Confirm final imprint width and proof before production.");
    return lines.join("\n");
  }

  function renderPills(checks){
    var safe = checks.some(function(c){ return c.title === "Safe margins pass"; });
    var contrast = checks.some(function(c){ return c.title === "Ink contrast pass"; });
    var text = checks.some(function(c){ return c.title === "Text size pass"; });

    var pillData = [
      safe ? "Margins pass" : "Margins need fix",
      contrast ? "Readable ink" : "Contrast risk",
      text ? "Text size ok" : "Text warning"
    ];

    var frag = document.createDocumentFragment();
    pillData.forEach(function(textValue){
      var pill = document.createElement("span");
      pill.className = "pill";
      pill.textContent = textValue;
      frag.appendChild(pill);
    });
    els.summaryPills.replaceChildren(frag);
  }

  function updateOutputs(){
    document.documentElement.style.setProperty("--shirt", els.shirtColor.value);
    var checks = buildChecks();
    var score = scoreFromChecks(checks);
    els.score.textContent = String(score);
    els.meterFill.style.width = score + "%";
    els.specPreview.textContent = buildSpec();
    renderIssues(checks);
    renderPills(checks);

    if(score >= 88){
      els.gradeBadge.textContent = "Order-ready";
    }else if(score >= 70){
      els.gradeBadge.textContent = "Needs minor fixes";
    }else{
      els.gradeBadge.textContent = "Press risk";
    }
  }

  function render(){
    renderBlocks();
    renderBlockList();
    updateOutputs();
  }

  function centerSelected(){
    var block = getSelected();
    if(!block){ return; }
    block.x = 50;
    render();
  }

  function deleteSelected(){
    if(!selectedId){ return; }
    blocks = blocks.filter(function(b){ return b.id !== selectedId; });
    selectedId = blocks.length ? blocks[0].id : null;
    render();
  }

  async function copySpec(){
    var text = buildSpec();
    els.manualBox.classList.remove("show");
    els.status.textContent = "";

    if(navigator.clipboard && window.isSecureContext){
      try{
        await navigator.clipboard.writeText(text);
        var verify = await navigator.clipboard.readText().catch(function(){ return text; });
        if(verify === text){
          els.status.textContent = "Spec copied. Paste it into your printer order notes.";
          return;
        }
      }catch(e){}
    }

    els.manualText.value = text;
    els.manualBox.classList.add("show");
    els.manualText.focus();
    els.manualText.select();
    els.status.textContent = "Clipboard was blocked. The spec is selected below; press Cmd+C or Ctrl+C.";
  }

  function downloadSpec(){
    var text = buildSpec();
    var blob = new Blob([text], {type:"text/plain;charset=utf-8"});
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    var safeName = (els.orderName.value.trim() || "tshirt-layout-spec")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-|-$/g, "");
    a.href = url;
    a.download = safeName + ".txt";
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
    els.status.textContent = "Spec downloaded as a text file.";
  }

  [els.orderName, els.shirtColor, els.printMethod, els.blockType, els.blockText, els.blockSize, els.inkColor].forEach(function(el){
    el.addEventListener("input", updateOutputs);
    el.addEventListener("change", updateOutputs);
  });

  els.addBlock.addEventListener("click", addBlockFromControls);
  els.centerSelected.addEventListener("click", centerSelected);
  els.deleteSelected.addEventListener("click", deleteSelected);
  els.resetDemo.addEventListener("click", resetSample);
  els.copySpec.addEventListener("click", copySpec);
  els.downloadSpec.addEventListener("click", downloadSpec);

  window.addEventListener("resize", updateOutputs);

  resetSample();
})();
</script>
</body>
